CREATE TABLE Agentic.MVP_AGENT (ID VARCHAR(36) PRIMARY KEY, Name VARCHAR(120) NOT NULL, ConfigJSON VARCHAR(32000) NOT NULL, Revision INTEGER NOT NULL, Enabled SMALLINT NOT NULL, IntervalSeconds INTEGER NOT NULL, NextDue DOUBLE NOT NULL, ActiveRun VARCHAR(36), UpdatedBy VARCHAR(200), UpdatedAt VARCHAR(40));
CREATE TABLE Agentic.MVP_RUN (ID VARCHAR(36) PRIMARY KEY, AgentID VARCHAR(36) NOT NULL REFERENCES Agentic.MVP_AGENT(ID), SnapshotJSON VARCHAR(32000) NOT NULL, State VARCHAR(20) NOT NULL, TriggerKind VARCHAR(20), Actor VARCHAR(200), CreatedAt VARCHAR(40), StartedEpoch DOUBLE, FinishedAt VARCHAR(40), Report VARCHAR(32000), ErrorCode VARCHAR(100));
CREATE TABLE Agentic.MVP_CALL (ID VARCHAR(36) PRIMARY KEY, RunID VARCHAR(36) NOT NULL REFERENCES Agentic.MVP_RUN(ID), ToolKey VARCHAR(100), ArgumentsJSON VARCHAR(4000), ResultJSON VARCHAR(32000), Outcome VARCHAR(20), CreatedAt VARCHAR(40));
